draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // face
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.stroke();

  // eyes
  ctx.beginPath();
  ctx.arc(W/2 - 20, H/2 - 20, 5, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 20, H/2 - 20, 5, 0, 2 * Math.PI);
  ctx.fill();

  // thought bubble
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 100 + 50 * Math.sin(t), 30, 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.stroke();

  // question mark
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('?', W/2, H/2 - 100 + 50 * Math.sin(t));

  ctx.restore();
}
